// Homepage filter. Reads data.json (generated by build.py from data/tools.csv).
(async()=>{const D=await (await fetch('data.json')).json();const $=i=>document.getElementById(i);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const q=new URLSearchParams(location.search);if(q.get('pos'))$('pos').value=q.get('pos');if(q.get('job'))$('cat').value=q.get('job');
function r(){const p=$('pos').value,c=$('cat').value,real=$('real').checked;
let rs=D.rows.filter(d=>D.pos.includes(d.pos)&&(!p||d.pos==p)&&(!c||d.category==c)&&(!real||!['none','coming_soon'].includes(d.level)));
const o={native:0,marketplace_app:1};rs.sort((a,b)=>(o[a.level]??5)-(o[b.level]??5)||a.tool.localeCompare(b.tool));
$('count').textContent=rs.length+' result'+(rs.length==1?'':'s');
$('results').innerHTML=rs.length?'<div class="tw"><table><thead><tr><th>Tool</th><th>POS</th><th>Job</th><th>Integration</th><th>Plan</th><th>Price from</th><th>Source</th></tr></thead><tbody>'+rs.map(d=>`<tr><td><a href="tools/${d.slug}/">${esc(d.tool)}</a></td><td>${esc(d.pos)}</td><td>${esc(d.category_label)}</td><td><span class="lv ${d.level}">${esc(d.level_label)}</span>${d.verified?'':' ⚠'}</td><td>${esc(d.plan)}</td><td>${esc(d.price)}</td><td><a rel="nofollow noopener" href="${esc(d.source)}">source</a> <small>${d.checked}</small></td></tr>`).join('')+'</tbody></table></div>':'<p>No tools found yet. <a href="suggest/">Suggest one</a>.</p>';
history.replaceState(null,'','?'+new URLSearchParams(Object.entries({pos:p,job:c}).filter(x=>x[1])));}
['pos','cat','real'].forEach(i=>$(i).onchange=r);r();})();
